-- MP-0047: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='dap' and type='party') then raise exception 'MP-0047: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='umno' and type='party') then raise exception 'MP-0047: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('liew-chin-tong','teo-nie-ching','ahmad-maslan') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0047: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('iskandar puteri','kulai','pontian') and slug not in ('liew-chin-tong','teo-nie-ching','ahmad-maslan')) then raise exception 'MP-0047: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0047:%' and (m.source_type <> 'editorial' or e.slug not in ('liew-chin-tong','teo-nie-ching','ahmad-maslan') or m.import_key not like 'MP-0047:' || e.slug || ':%')) then raise exception 'MP-0047: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'liew-chin-tong','Liew Chin Tong','government','Deputy Minister of Finance','Iskandar Puteri','Johor','Liew Chin Tong represents Iskandar Puteri, Johor, in the Dewan Rakyat. Current role: Deputy Minister of Finance. Affiliated with DAP.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4201','/portraits/liew-chin-tong.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P162.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4201"}, {"label": "DAP · current Johor representatives", "url": "https://dapmalaysia.org/johor-representatives/"}, {"label": "Representative · current Finance portfolio and former Perling seat", "url": "https://liewchintong.com/about/"}]'::jsonb from public.entities parent where parent.slug='dap' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'teo-nie-ching','Teo Nie Ching','government','Deputy Minister of Communications','Kulai','Johor','Teo Nie Ching represents Kulai, Johor, in the Dewan Rakyat. Current role: Deputy Minister of Communications. Affiliated with DAP.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4202','/portraits/teo-nie-ching.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P163.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4202"}, {"label": "DAP · current Johor representatives", "url": "https://dapmalaysia.org/johor-representatives/"}]'::jsonb from public.entities parent where parent.slug='dap' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'ahmad-maslan','Ahmad Maslan','government','Deputy Minister of Works','Pontian','Johor','Ahmad Maslan represents Pontian, Johor, in the Dewan Rakyat. Current role: Deputy Minister of Works. Affiliated with UMNO.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4203','/portraits/ahmad-maslan.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P164.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4203"}, {"label": "UMNO · current supreme council member, 3 September 2026", "url": "https://umno-online.my/2026/09/03/inisiatif-presiden-umno-penuhi-keperluan-parti-dan-rakyat-ahmad-maslan/"}]'::jsonb from public.entities parent where parent.slug='umno' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('liew-chin-tong','teo-nie-ching','ahmad-maslan') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0047: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0047:teo-nie-ching:stpm-incentives-111','Deliver RM92,000 in incentives and registration assistance to 111 Kulai students','Education','achieved',null,null,null,null,'2026-08-23','https://www.bernama.com/en/general/news.php?id=2598047','Teo presented the assistance to outstanding 2025 STPM students in her constituency.','Achieved covers the reported presentation on 23 August. The separate RM1.3 million annual education allocation is not a completion denominator or evidence that all school projects were finished.','2026-11-10','editorial',false from public.entities e where e.slug='teo-nie-ching' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0047:teo-nie-ching:kampung-separa-flood-aid','Provide assistance to 32 Kampung Separa flood-affected families','Social Welfare','achieved',null,null,null,null,'2026-05-25','https://themalaysiapress.com/2026/05/25/nie-ching-santuni-mangsa-banjir-lumpur-kg-separa-32-keluarga-terima-bantuan/','Teo’s constituency response provided contributions to the 32 families affected by the 8 May mud flood.','The 25 May report describes a Sunday handover. This records that assistance only; drainage repairs, housing compensation, causal findings and protection from future flooding were not verified.','2026-11-10','editorial',false from public.entities e where e.slug='teo-nie-ching' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0047:ahmad-maslan:classroom-projects-2027-intake','Implement 524 additional-classroom projects for the 2027 school intake','Education','in_progress',1,null,null,null,'2026-08-17','https://www.bernama.com/radio/news.php?id=2595381','Ahmad reported 524 projects valued at RM668 million across 459 schools. Three projects were complete and 517 had received acceptance letters at the August snapshot.','Progress is 3 completed projects / 524 projects, rounded to 1%, as reported on 17 August. It is a historical project-count ratio, not a November update, a proportion of classrooms or weighted physical progress. Acceptance letters are not completed buildings. JKR and the Education Ministry share delivery.','2026-11-10','editorial',false from public.entities e where e.slug='ahmad-maslan' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

